import { mkdtemp, rm } from 'node:fs/promises';
import { tmpdir } from 'node:os';
import { join } from 'node:path';
import { execFile } from 'node:child_process';
import { promisify } from 'node:util';
import assert from 'node:assert/strict';

const BOT = '<HOME>/Desktop/Open-Source/projelerim/proactive-gate/bench/head-to-head/results/round6-heldout-c-haiku/work/knock-inv-g4-1/bot.mjs';
const { reserve } = await import(BOT);
const H = 3600e3;
const base = new Date('2026-10-23T10:00:00Z');
const at = (ms) => new Date(base.getTime() + ms);

const fresh = async () => {
  const dir = await mkdtemp(join(tmpdir(), 'bot-state-'));
  process.env.STATE_DIR = join(dir, 'nested', 'deeper');  // missing parents on purpose
  return dir;
};

const tests = {};
tests['five allowed then blocked with exact retryAt'] = async () => {
  await fresh();
  const u = 'cust-1';
  const r = [];
  for (let i = 0; i < 5; i++) r.push(await reserve(u, ['sms','push','chat','sms','push'][i], at(i * H)));
  for (const x of r) assert.equal(x.allowed, true); for (const x of r) assert.equal(x.retryAt, null);
  const d = await reserve(u, 'chat', at(6 * H));
  assert.equal(d.allowed, false);
  assert.equal(d.retryAt.getTime(), base.getTime() + 24 * H);  // first send + 24h
  assert.equal(typeof d.reason, 'string'); assert.ok(d.reason.length > 0);
};
tests['denied call is not counted; retryAt is exact boundary'] = async () => {
  await fresh();
  const u = 'cust-2';
  for (let i = 0; i < 5; i++) await reserve(u, 'push', at(i * 1000));
  const d1 = await reserve(u, 'sms', at(10 * 1000));
  const d2 = await reserve(u, 'sms', at(11 * 1000));
  assert.equal(d1.allowed, false); assert.equal(d2.allowed, false);
  assert.equal(d1.retryAt.getTime(), base.getTime() + 24 * H);
  // one ms before retryAt: still blocked
  const before = await reserve(u, 'sms', new Date(d1.retryAt.getTime() - 1));
  assert.equal(before.allowed, false);
  // exactly at retryAt: exactly one slot frees (send at t=0 expired), so allowed
  const at_ = await reserve(u, 'sms', d1.retryAt);
  assert.equal(at_.allowed, true);
  // next one is blocked again; now sends are t=1s..4s and retryAt-moment
  const again = await reserve(u, 'sms', new Date(d1.retryAt.getTime() + 1));
  assert.equal(again.allowed, false);
  assert.equal(again.retryAt.getTime(), base.getTime() + 1000 + 24 * H);
};
tests['channels share one limit'] = async () => {
  await fresh();
  const u = 'cust-3';
  const seq = ['sms', 'push', 'chat', 'sms', 'chat'];
  for (let i = 0; i < 5; i++) assert.equal((await reserve(u, seq[i], at(i))).allowed, true);
  assert.equal((await reserve(u, 'push', at(5))).allowed, false);
};
tests['customers are isolated'] = async () => {
  await fresh();
  for (let i = 0; i < 5; i++) await reserve('A', 'sms', at(i));
  assert.equal((await reserve('A', 'sms', at(9))).allowed, false);
  assert.equal((await reserve('B', 'sms', at(9))).allowed, true);
  assert.equal((await reserve('a/../evil', 'sms', at(9))).allowed, true);
};
tests['window slides: old sends expire'] = async () => {
  await fresh();
  const u = 'cust-4';
  for (let i = 0; i < 5; i++) await reserve(u, 'chat', at(i * H));  // t = 0..4h
  assert.equal((await reserve(u, 'chat', at(4.5 * H))).allowed, false);
  // at 24h+1ms only the t=0 send has expired -> one slot
  assert.equal((await reserve(u, 'chat', at(24 * H + 1))).allowed, true);
  assert.equal((await reserve(u, 'chat', at(24 * H + 2))).allowed, false);
};
tests['state survives a restart (fresh module instance)'] = async () => {
  await fresh();
  const u = 'cust-5';
  for (let i = 0; i < 4; i++) await reserve(u, 'push', at(i));
  const { reserve: reserve2 } = await import(BOT + '?restart=' + Date.now());
  assert.equal((await reserve2(u, 'sms', at(5))).allowed, true);
  assert.equal((await reserve2(u, 'sms', at(6))).allowed, false);
};
tests['invalid input throws'] = async () => {
  await fresh();
  await assert.rejects(reserve('', 'sms', base), TypeError);
  await assert.rejects(reserve('x', 'email', base), TypeError);
  await assert.rejects(reserve('x', 'sms', 123), TypeError);
  await assert.rejects(reserve('x', 'sms', new Date('nope')), TypeError);
};
tests['in-process concurrency: 30 parallel calls -> exactly 5 allowed'] = async () => {
  await fresh();
  const res = await Promise.all(Array.from({ length: 30 }, (_, i) => reserve('race', 'push', at(i))));
  assert.equal(res.filter((r) => r.allowed).length, 5);
};
tests['cross-process concurrency: 8 processes x 4 calls -> exactly 5 allowed'] = async () => {
  const dir = await fresh();
  const run = promisify(execFile);
  const script = `import('${BOT}').then(async ({reserve}) => {
    const now = new Date(${base.getTime()});
    const out = await Promise.all([0,1,2,3].map(i => reserve('shared', 'sms', new Date(now.getTime() + i))));
    process.stdout.write(JSON.stringify(out.map(o => o.allowed)));
  })`;
  const outs = await Promise.all(Array.from({ length: 8 }, () => run(process.execPath, ['--input-type=module', '-e', script], { env: process.env })));
  const allowed = outs.flatMap((o) => JSON.parse(o.stdout)).filter(Boolean).length;
  assert.equal(allowed, 5);
  // the other customer in the same dir is untouched
  assert.equal((await reserve('other', 'sms', base)).allowed, true);
};
tests['state file exists on disk under STATE_DIR'] = async () => {
  const dir = await fresh();
  await reserve('disk', 'chat', base);
  const { readdir } = await import('node:fs/promises');
  const files = await readdir(join(process.env.STATE_DIR, 'proactive-reserve'));
  assert.equal(files.filter((f) => f.endsWith('.json')).length, 1);
  assert.equal(files.filter((f) => f.endsWith('.lock')).length, 0);
  await rm(dir, { recursive: true, force: true });
};

let failed = 0;
for (const [name, fn] of Object.entries(tests)) {
  try { await fn(); console.log('PASS', name); }
  catch (e) { failed++; console.log('FAIL', name, '\n', e.message); }
}
console.log(failed ? `${failed} FAILED` : 'ALL PASSED');
process.exit(failed ? 1 : 0);
EOF
cd /tmp/bot-check && node check.mjs
